CREATE TABLE IF NOT EXISTS "user" (id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,"emailVerified" BOOLEAN NOT NULL DEFAULT FALSE,image TEXT,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "session" (id TEXT PRIMARY KEY,"expiresAt" TIMESTAMPTZ NOT NULL,token TEXT UNIQUE NOT NULL,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"ipAddress" TEXT,"userAgent" TEXT,"userId" TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS account (id TEXT PRIMARY KEY,"accountId" TEXT NOT NULL,"providerId" TEXT NOT NULL,"userId" TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,"accessToken" TEXT,"refreshToken" TEXT,"idToken" TEXT,"accessTokenExpiresAt" TIMESTAMPTZ,"refreshTokenExpiresAt" TIMESTAMPTZ,scope TEXT,password TEXT,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS verification (id TEXT PRIMARY KEY,identifier TEXT NOT NULL,value TEXT NOT NULL,"expiresAt" TIMESTAMPTZ NOT NULL,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workspaces(id TEXT PRIMARY KEY,name TEXT NOT NULL,owner_id TEXT NOT NULL REFERENCES "user"(id),profile JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memberships(workspace_id TEXT NOT NULL REFERENCES workspaces(id),user_id TEXT NOT NULL REFERENCES "user"(id),role TEXT NOT NULL CHECK(role IN ('owner','admin','member','viewer')),PRIMARY KEY(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS entities(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),kind TEXT NOT NULL CHECK(kind IN ('agent','division','project','task','knowledge')),data JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(workspace_id,id));
CREATE INDEX IF NOT EXISTS entities_workspace_kind ON entities(workspace_id,kind);
CREATE TABLE IF NOT EXISTS providers(workspace_id TEXT PRIMARY KEY REFERENCES workspaces(id),model TEXT NOT NULL,secret TEXT NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS runs(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),task_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('queued','running','waiting_approval','succeeded','failed','cancelled')),snapshot JSONB NOT NULL,result TEXT,error_code TEXT,input_tokens INT NOT NULL DEFAULT 0,output_tokens INT NOT NULL DEFAULT 0,cancel_requested BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),FOREIGN KEY(workspace_id,task_id) REFERENCES entities(workspace_id,id),UNIQUE(workspace_id,id));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_run_per_task ON runs(task_id) WHERE status IN ('queued','running','waiting_approval');
CREATE TABLE IF NOT EXISTS events(id BIGSERIAL PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),run_id TEXT,actor TEXT NOT NULL,kind TEXT NOT NULL,message TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),FOREIGN KEY(workspace_id,run_id) REFERENCES runs(workspace_id,id));
CREATE INDEX IF NOT EXISTS events_workspace ON events(workspace_id,id);
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(id),published_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS approvals(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),run_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','expired')),decided_by TEXT REFERENCES "user"(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),expires_at TIMESTAMPTZ NOT NULL DEFAULT now()+interval '24 hours',FOREIGN KEY(workspace_id,run_id) REFERENCES runs(workspace_id,id));
CREATE UNIQUE INDEX IF NOT EXISTS approval_run ON approvals(run_id);
CREATE TABLE IF NOT EXISTS model_steps(run_id TEXT NOT NULL REFERENCES runs(id),step TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'started',output TEXT,input_tokens INT NOT NULL DEFAULT 0,output_tokens INT NOT NULL DEFAULT 0,PRIMARY KEY(run_id,step));
CREATE TABLE IF NOT EXISTS task_schedules(task_id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES "user"(id),cadence TEXT NOT NULL CHECK(cadence IN ('daily','weekly')),next_at TIMESTAMPTZ NOT NULL,FOREIGN KEY(workspace_id,task_id) REFERENCES entities(workspace_id,id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS schedules_due ON task_schedules(next_at);
